package br.com.mvdelivery.repository;
import java.sql.*;import java.util.*;import java.time.*;import java.lang.reflect.*;import br.com.mvdelivery.model.*;
public class JdbcRepository implements Repository {
 private final Connection db;
 public JdbcRepository(String url,String user,String password)throws SQLException{db=DriverManager.getConnection(url,user,password);}
 public List<Object> list(Schema s)throws Exception{List<Object> out=new ArrayList<>();try(PreparedStatement q=db.prepareStatement("SELECT "+String.join(",",s.columns)+" FROM "+s.table+" ORDER BY "+s.columns[0]);ResultSet rs=q.executeQuery()){while(rs.next()){Object o=s.create();for(int i=0;i<s.fields.length;i++){Field f=s.fields[i];Class<?> t=f.getType();String col=s.columns[i];Schema rel=Schema.of(t);Object v;if(rel!=null){int id=rs.getInt(col);v=rs.wasNull()?null:find(rel,id);}else if(t==int.class)v=rs.getInt(col);else if(t==boolean.class)v=rs.getBoolean(col);else if(t==LocalDateTime.class)v=rs.getTimestamp(col).toLocalDateTime();else if(t==java.math.BigDecimal.class)v=rs.getBigDecimal(col);else if(t==StatusPedido.class)v=StatusPedido.valueOf(rs.getString(col));else v=rs.getString(col);f.set(o,v);}out.add(o);}}return out;}
 private void bind(PreparedStatement q,int index,Field f,Object o)throws Exception{Object v=f.get(o);Schema rel=Schema.of(f.getType());if(v==null)q.setObject(index,null);else if(rel!=null)q.setInt(index,rel.id(v));else if(v instanceof LocalDateTime)q.setTimestamp(index,Timestamp.valueOf((LocalDateTime)v));else if(v instanceof Enum)q.setString(index,((Enum<?>)v).name());else q.setObject(index,v);}
 private void write(Schema s,Object o)throws Exception{int id=s.id(o);String[] cols=Arrays.copyOfRange(s.columns,1,s.columns.length);String sql;if(id==0)sql="INSERT INTO "+s.table+" ("+String.join(",",cols)+") VALUES ("+String.join(",",Collections.nCopies(cols.length,"?"))+")";else sql="UPDATE "+s.table+" SET "+String.join("=?,",cols)+"=? WHERE "+s.columns[0]+"=?";try(PreparedStatement q=db.prepareStatement(sql,Statement.RETURN_GENERATED_KEYS)){for(int i=1;i<s.fields.length;i++)bind(q,i,s.fields[i],o);if(id!=0)q.setInt(s.fields.length,id);q.executeUpdate();if(id==0)try(ResultSet keys=q.getGeneratedKeys()){if(!keys.next())throw new SQLException("ID não retornado");s.fields[0].setInt(o,keys.getInt(1));}}}
 public void save(Schema s,Object o)throws Exception{int original=s.id(o);db.setAutoCommit(false);try{Object old=find(s,original);Rules.validate(this,s,o);write(s,o);if(s==Schema.PEDIDO&&(old==null||((Pedido)old).status!=((Pedido)o).status)){HistoricoStatus h=new HistoricoStatus();h.pedido=(Pedido)o;h.status=h.pedido.status;h.dataHora=LocalDateTime.now();h.observacoes="Registro automático";write(Schema.HISTORICO,h);}db.commit();}catch(Exception e){db.rollback();s.fields[0].setInt(o,original);throw e;}finally{db.setAutoCommit(true);}}
 private void remove(String table,String col,int id)throws SQLException{try(PreparedStatement q=db.prepareStatement("DELETE FROM "+table+" WHERE "+col+"=?")){q.setInt(1,id);q.executeUpdate();}}
 public void delete(Schema s,int id)throws Exception{db.setAutoCommit(false);try{Rules.checkDelete(this,s,id);if(s==Schema.PEDIDO){remove("historico_status","id_pedido",id);remove("feedback","id_pedido",id);}remove(s.table,s.columns[0],id);db.commit();}catch(Exception e){db.rollback();throw e;}finally{db.setAutoCommit(true);}}
}
